<?php
declare(strict_types=1);
require dirname(__DIR__).'/src/bootstrap.php';
$app=new Nshir\App();$db=$app->db();$user=$app->user();$path=trim(parse_url($_SERVER['REQUEST_URI']??'/',PHP_URL_PATH)?:'/','/');
function e(?string $v):string{return htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8');}
function go(string $p):never{header('Location:'.$p);exit;}
function layout(string $title,string $body,?array $user,string $desc='إعلانات مبوبة عربية بسيطة وسريعة'):void{?>
<!doctype html><html lang="ar" dir="rtl"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?=e($title)?> | نشر</title><meta name="description" content="<?=e($desc)?>"><link rel="canonical" href="<?=e(rtrim((string)(getenv('APP_URL')?:'https://nshir.com'),'/').(parse_url($_SERVER['REQUEST_URI']??'/',PHP_URL_PATH)?:'/'))?>"><link rel="stylesheet" href="/assets/app.css"><script src="/assets/app.js" defer></script></head><body><header class="top"><div class="wrap"><a class="logo" href="/"><b>ن</b>شر</a><nav class="nav"><a class="btn hide-sm" href="/">تصفح</a><?php if($user):?><a class="btn" href="/profile"><?=e($user['name'])?></a><a class="btn primary" href="/publish">نشر إعلان</a><?php else:?><a class="btn" href="/login">دخول</a><a class="btn primary" href="/register">تسجيل</a><?php endif;?></nav></div></header><?=$body?></body></html><?php}
function children(PDO $db,string $table,?int $parent):array{$sql="SELECT id,name,slug FROM $table WHERE ".($parent===null?'parent_id IS NULL':'parent_id=?')." AND is_active=1 ORDER BY sort_order,name";$q=$db->prepare($sql);$q->execute($parent===null?[]:[$parent]);return$q->fetchAll();}
function leaf(PDO$db,int$id):bool{$q=$db->prepare('SELECT 1 FROM categories WHERE parent_id=? AND is_active=1 LIMIT 1');$q->execute([$id]);return!$q->fetchColumn();}
function cards(array$ads):string{ob_start();?><section id="ads" class="grid"><?php if(!$ads):?><div class="empty">لا توجد إعلانات هنا حتى الآن.</div><?php endif;foreach($ads as$a):?><article class="ad"><a href="/ad/<?=$a['id']?>"><div class="photo">صورة الإعلان</div><div class="info"><?php if($a['price']!==null):?><div class="price"><?=number_format((float)$a['price'])?> ر.س</div><?php endif;?><div class="title"><?=e($a['title'])?></div><div class="meta"><?=e($a['location_name']??'')?></div></div></a></article><?php endforeach;?></section><?php return ob_get_clean();}

if($path==='login'){
 if($_SERVER['REQUEST_METHOD']==='POST'){$app->verifyCsrf();$q=$db->prepare('SELECT * FROM users WHERE email=? AND status="active"');$q->execute([mb_strtolower(trim($_POST['email']??''))]);$u=$q->fetch();if(!$u||!password_verify((string)($_POST['password']??''),$u['password_hash'])){http_response_code(422);$err='بيانات الدخول غير صحيحة.';}else{session_regenerate_id(true);$_SESSION['uid']=$u['id'];$q=$db->prepare('UPDATE users SET last_login_ip=INET6_ATON(?) WHERE id=?');$q->execute([$app->clientIp(),$u['id']]);go('/');}}
 ob_start();?><main class="wrap hero"><h1>تسجيل الدخول</h1><?php if(isset($err)):?><p><?=$err?></p><?php endif;?><form class="panel" method="post"><input type="hidden" name="_token" value="<?=e($app->csrf())?>"><div class="field"><label>البريد</label><input type="email" name="email" required></div><div class="field"><label>كلمة المرور</label><input type="password" name="password" required></div><button class="btn primary">دخول</button></form></main><?php layout('دخول',ob_get_clean(),$user);exit;
}
if($path==='register'){
 if($_SERVER['REQUEST_METHOD']==='POST'){$app->verifyCsrf();$email=mb_strtolower(trim($_POST['email']??''));$name=trim($_POST['name']??'');$pass=(string)($_POST['password']??'');if(!filter_var($email,FILTER_VALIDATE_EMAIL)||mb_strlen($name)<2||strlen($pass)<8){http_response_code(422);exit('تحقق من البيانات.');}$geo=(new Nshir\GeoIp($app))->locate($app->clientIp());$loc=$geo['location']??null;if(!$loc){http_response_code(422);exit('تعذر تحديد موقعك تلقائيًا. يمكنك المحاولة لاحقًا أو اختيار الموقع من البروفايل.');}$country=$loc;while($country&&$country['parent_id']){$q=$db->prepare('SELECT id,parent_id,name,type FROM locations WHERE id=?');$q->execute([$country['parent_id']]);$country=$q->fetch();}$token=bin2hex(random_bytes(32));$q=$db->prepare('INSERT INTO users(email,name,password_hash,country_id,city_id,registration_ip,verify_token_hash) VALUES(?,?,?,?,?,INET6_ATON(?),?)');$q->execute([$email,$name,password_hash($pass,PASSWORD_DEFAULT),$country['id'],$loc['id'],$app->clientIp(),hash('sha256',$token)]);exit('تم إنشاء الحساب. يلزم تفعيل البريد قبل النشر.');}
 ob_start();?><main class="wrap hero"><h1>حساب جديد</h1><p class="muted">البريد، الاسم، وكلمة المرور. سنحدد موقعك تلقائيًا من IP ويمكن تعديله لاحقًا.</p><form class="panel" method="post"><input type="hidden" name="_token" value="<?=e($app->csrf())?>"><div class="field"><label>البريد</label><input name="email" type="email" required></div><div class="field"><label>الاسم</label><input name="name" required maxlength="80"></div><div class="field"><label>كلمة المرور</label><input name="password" type="password" minlength="8" required></div><button class="btn primary">إنشاء الحساب</button></form></main><?php layout('تسجيل',ob_get_clean(),$user);exit;
}
if($path==='profile'){if(!$user)go('/login');$q=$db->prepare('SELECT c.name country,ci.name city,a.name area FROM users u JOIN locations c ON c.id=u.country_id LEFT JOIN locations ci ON ci.id=u.city_id LEFT JOIN locations a ON a.id=u.area_id WHERE u.id=?');$q->execute([$user['id']]);$loc=$q->fetch();ob_start();?><main class="wrap hero"><h1><?=e($user['name'])?></h1><div class="panel"><p><?=e($user['email'])?></p><p><b>الموقع:</b> <?=e(implode('، ',array_filter([$loc['country'],$loc['city'],$loc['area']])))?></p><p class="muted">هذا الموقع يستخدم تلقائيًا عند نشر إعلان.</p></div></main><?php layout('الملف الشخصي',ob_get_clean(),$user);exit;}
if(str_starts_with($path,'location/')){$id=(int)substr($path,9);$q=$db->prepare('SELECT * FROM locations WHERE id=? AND is_active=1');$q->execute([$id]);$loc=$q->fetch();if(!$loc){http_response_code(404);exit('غير موجود');}$kids=children($db,'locations',$id);$q=$db->prepare("SELECT a.id,a.title,a.price,l.name location_name FROM ads a JOIN locations l ON l.id=a.country_id WHERE a.status='published' AND (a.country_id=? OR a.city_id=? OR a.area_id=?) ORDER BY a.created_at DESC LIMIT 24");$q->execute([$id,$id,$id]);$ads=$q->fetchAll();ob_start();?><main class="wrap hero"><div class="crumbs"><a href="/">الرئيسية</a> / <?=e($loc['name'])?></div><h1>إعلانات <?=e($loc['name'])?></h1><?php if($kids):?><div class="chips"><?php foreach($kids as$k):?><a class="chip" href="/location/<?=$k['id']?>"><?=e($k['name'])?></a><?php endforeach;?></div><?php endif;?><?=cards($ads)?></main><?php layout('إعلانات '.$loc['name'],ob_get_clean(),$user);exit;}
if(str_starts_with($path,'category/')){$id=(int)substr($path,9);$q=$db->prepare('SELECT * FROM categories WHERE id=? AND is_active=1');$q->execute([$id]);$cat=$q->fetch();if(!$cat){http_response_code(404);exit('غير موجود');}$kids=children($db,'categories',$id);$q=$db->prepare("SELECT a.id,a.title,a.price,l.name location_name FROM ads a JOIN locations l ON l.id=a.country_id WHERE a.status='published' AND a.category_id=? ORDER BY a.created_at DESC LIMIT 24");$q->execute([$id]);$ads=$q->fetchAll();ob_start();?><main class="wrap hero"><div class="crumbs"><a href="/">الرئيسية</a> / <?=e($cat['name'])?></div><h1><?=e($cat['name'])?></h1><?php if($kids):?><div class="chips"><?php foreach($kids as$k):?><a class="chip" href="/category/<?=$k['id']?>"><?=e($k['name'])?></a><?php endforeach;?></div><?php else:?><p class="muted">آخر تصنيف — النشر متاح هنا.</p><?php endif;?><?=cards($ads)?></main><?php if(!$kids):?><a class="btn primary publish" href="/publish?category=<?=$id?>">＋ نشر إعلان</a><?php endif;layout($cat['name'],ob_get_clean(),$user);exit;}
if(str_starts_with($path,'ad/')){$id=(int)substr($path,3);$q=$db->prepare("SELECT a.*,u.name user_name,c.name category_name,l.name location_name FROM ads a JOIN users u ON u.id=a.user_id JOIN categories c ON c.id=a.category_id JOIN locations l ON l.id=a.country_id WHERE a.id=? AND a.status='published'");$q->execute([$id]);$ad=$q->fetch();if(!$ad){http_response_code(404);exit('الإعلان غير موجود');}$db->prepare('UPDATE ads SET views=views+1 WHERE id=?')->execute([$id]);ob_start();?><main class="wrap hero"><div class="crumbs"><a href="/">الرئيسية</a> / <a href="/category/<?=$ad['category_id']?>"><?=e($ad['category_name'])?></a></div><article class="panel"><h1><?=e($ad['title'])?></h1><?php if($ad['price']!==null):?><div class="price"><?=number_format((float)$ad['price'])?> ر.س</div><?php endif;?><p><?=nl2br(e($ad['body']))?></p><hr><p class="muted"><?=e($ad['location_name'])?> · <?=e($ad['user_name'])?> · <?=$ad['views']+1?> مشاهدة</p></article></main><?php layout($ad['title'],ob_get_clean(),$user,mb_substr($ad['body'],0,150));exit;}
if($path==='publish'){if(!$user)go('/login');$cid=(int)($_GET['category']??$_POST['category_id']??0);if(!$cid){$roots=children($db,'categories',null);ob_start();?><main class="wrap hero"><h1>اختر القسم</h1><p class="muted">تابع حتى آخر تصنيف، وبعدها يظهر نموذج الإعلان.</p><div class="chips"><?php foreach($roots as$c):?><a class="chip" href="/category/<?=$c['id']?>"><?=e($c['name'])?></a><?php endforeach;?></div></main><?php layout('اختر التصنيف',ob_get_clean(),$user);exit;}if(!leaf($db,$cid))go('/category/'.$cid);if($_SERVER['REQUEST_METHOD']==='POST'){$app->verifyCsrf();$title=trim($_POST['title']??'');$body=trim($_POST['body']??'');$price=($_POST['price']??'')!==''?(float)$_POST['price']:null;if(mb_strlen($title)<3||mb_strlen($body)<3){http_response_code(422);exit('العنوان والمحتوى مطلوبان.');}$q=$db->prepare('INSERT INTO ads(user_id,category_id,country_id,city_id,area_id,title,slug,body,price,publish_ip) VALUES(?,?,?,?,?,?,?,?,?,INET6_ATON(?))');$q->execute([$user['id'],$cid,$user['country_id'],$user['city_id'],$user['area_id'],$title,$app->slug($title),$body,$price,$app->clientIp()]);go('/ad/'.$db->lastInsertId());}ob_start();?><main class="wrap hero"><h1>نشر إعلان</h1><p class="muted">الموقع يؤخذ من بروفايلك تلقائيًا.</p><form class="panel" method="post" enctype="multipart/form-data"><input type="hidden" name="_token" value="<?=e($app->csrf())?>"><input type="hidden" name="category_id" value="<?=$cid?>"><div class="field"><label>العنوان</label><input name="title" maxlength="160" required></div><div class="field"><label>المحتوى</label><textarea name="body" required></textarea></div><div class="field"><label>السعر</label><input name="price" type="number" min="0" step=".01"></div><div class="field"><label>الصور</label><input name="images[]" type="file" accept="image/jpeg,image/png,image/webp" multiple></div><button class="btn primary">نشر الآن</button></form></main><?php layout('نشر إعلان',ob_get_clean(),$user);exit;}
$cats=children($db,'categories',null);$countries=children($db,'locations',null);$ads=$db->query("SELECT a.id,a.title,a.price,l.name location_name FROM ads a JOIN locations l ON l.id=a.country_id WHERE a.status='published' ORDER BY a.created_at DESC LIMIT 24")->fetchAll();ob_start();?><main class="wrap"><section class="hero"><h1>انشر وابحث ببساطة</h1><p class="muted">كل الدول وكل الأقسام أمامك. ادخل بالتدرج للموقع أو التصنيف.</p><div class="filters"><?php foreach($countries as$l):?><a class="chip" href="/location/<?=$l['id']?>"><?=e($l['name'])?></a><?php endforeach;?></div><div class="chips"><?php foreach($cats as$c):?><a class="chip" href="/category/<?=$c['id']?>"><?=e($c['name'])?></a><?php endforeach;?></div></section><div class="section-title"><h2>أحدث الإعلانات</h2><div><button class="btn" data-view="grid">كروت</button> <button class="btn" data-view="list">قائمة</button></div></div><?=cards($ads)?></main><?php layout('إعلانات مبوبة',ob_get_clean(),$user);
